## What Problem This Solves

Fixes an issue where memory-core dreaming could buffer an oversized daily memory markdown file or `DREAMS.md` before updating its managed dreaming block.

## Why This Change Was Made

Dreaming markdown updates now use the same bounded production file reader for daily inline phase blocks and deep `DREAMS.md` summaries. Valid markdown files still update normally, while oversized files fail before managed-block replacement or memory event writes.

## User Impact

Users get an early local error for oversized dreaming markdown files instead of unbounded memory growth during light, REM, or deep dreaming.

## Evidence

- Real call-chain proof: production memory-core dreaming markdown updates valid daily/deep files and rejects oversized daily/deep files without writing memory events.
- Focused tests: memory-core dreaming markdown storage still passes existing behavior tests plus the new oversized file coverage.

```text
$ ./node_modules/.bin/esbuild ../../outputs/local-memory-dreaming-markdown-cap/proof-live.ts --bundle --platform=node --format=esm --packages=external --alias:openclaw/plugin-sdk=./src/plugin-sdk --outfile=.proof-live.mjs && node .proof-live.mjs
valid: daily=true dailyInserted=true deepInserted=true
oversized-daily: rejected=true eventsWritten=false
oversized-deep: rejected=true eventsWritten=false

$ node scripts/run-vitest.mjs extensions/memory-core/src/dreaming-markdown.test.ts
Test Files  1 passed (1)
Tests  11 passed (11)
```

<details>
<summary>proof-live.ts</summary>

```ts
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { MEMORY_DREAMING_MARKDOWN_MAX_BYTES } from "./extensions/memory-core/src/dreaming-dreams-file.ts";
import {
  writeDailyDreamingPhaseBlock,
  writeDeepDreamingReport,
} from "./extensions/memory-core/src/dreaming-markdown.ts";

async function exists(targetPath: string): Promise<boolean> {
  return await fs.access(targetPath).then(
    () => true,
    () => false,
  );
}

async function main() {
  const tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "openclaw-memory-dreaming-proof-"));
  try {
    const validWorkspace = path.join(tempRoot, "valid");
    await fs.mkdir(validWorkspace, { recursive: true });
    const validDailyPath = path.join(validWorkspace, "memory", "2026-04-05.md");
    await fs.mkdir(path.dirname(validDailyPath), { recursive: true });
    await fs.writeFile(validDailyPath, "# Daily\n\nExisting note.\n", "utf8");

    const validDaily = await writeDailyDreamingPhaseBlock({
      workspaceDir: validWorkspace,
      phase: "light",
      bodyLines: ["- Proof: bounded daily markdown still updates."],
      nowMs: Date.parse("2026-04-05T10:00:00Z"),
      timezone: "UTC",
      storage: { mode: "inline", separateReports: false },
    });
    const dailyContent = await fs.readFile(validDailyPath, "utf8");
    await writeDeepDreamingReport({
      workspaceDir: validWorkspace,
      bodyLines: ["- Proof: bounded DREAMS.md still updates."],
      nowMs: Date.parse("2026-04-05T10:00:00Z"),
      timezone: "UTC",
      storage: { mode: "inline", separateReports: false },
    });
    const dreamsContent = await fs.readFile(path.join(validWorkspace, "DREAMS.md"), "utf8");
    console.log(
      `valid: daily=${Boolean(validDaily.inlinePath)} dailyInserted=${dailyContent.includes("bounded daily markdown")} deepInserted=${dreamsContent.includes("bounded DREAMS.md")}`,
    );

    const oversizedDailyWorkspace = path.join(tempRoot, "oversized-daily");
    const oversizedDailyPath = path.join(oversizedDailyWorkspace, "memory", "2026-04-05.md");
    await fs.mkdir(path.dirname(oversizedDailyPath), { recursive: true });
    await fs.writeFile(oversizedDailyPath, Buffer.alloc(MEMORY_DREAMING_MARKDOWN_MAX_BYTES + 1));
    try {
      await writeDailyDreamingPhaseBlock({
        workspaceDir: oversizedDailyWorkspace,
        phase: "rem",
        bodyLines: ["- Proof: should not write."],
        nowMs: Date.parse("2026-04-05T10:00:00Z"),
        timezone: "UTC",
        storage: { mode: "inline", separateReports: false },
      });
      console.log("oversized-daily: unexpected success");
      process.exitCode = 1;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const eventsWritten = await exists(path.join(oversizedDailyWorkspace, "memory-events.jsonl"));
      console.log(
        `oversized-daily: rejected=${message.includes(`File exceeds ${MEMORY_DREAMING_MARKDOWN_MAX_BYTES} bytes`)} eventsWritten=${eventsWritten}`,
      );
    }

    const oversizedDeepWorkspace = path.join(tempRoot, "oversized-deep");
    const oversizedDreamsPath = path.join(oversizedDeepWorkspace, "DREAMS.md");
    await fs.mkdir(oversizedDeepWorkspace, { recursive: true });
    await fs.writeFile(oversizedDreamsPath, Buffer.alloc(MEMORY_DREAMING_MARKDOWN_MAX_BYTES + 1));
    try {
      await writeDeepDreamingReport({
        workspaceDir: oversizedDeepWorkspace,
        bodyLines: ["- Proof: should not write."],
        nowMs: Date.parse("2026-04-05T10:00:00Z"),
        timezone: "UTC",
        storage: { mode: "inline", separateReports: false },
      });
      console.log("oversized-deep: unexpected success");
      process.exitCode = 1;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const eventsWritten = await exists(path.join(oversizedDeepWorkspace, "memory-events.jsonl"));
      console.log(
        `oversized-deep: rejected=${message.includes(`File exceeds ${MEMORY_DREAMING_MARKDOWN_MAX_BYTES} bytes`)} eventsWritten=${eventsWritten}`,
      );
    }
  } finally {
    await fs.rm(tempRoot, { recursive: true, force: true });
  }
}

void main();
```

</details>

